import React, { useEffect, useState } from "react";
import { Button, Container } from "@mui/material";
import axios from "axios";
import AuthForm from "./components/AuthForm";
import EventForm from "./components/EventForm";
import EventList from "./components/EventList";
import { initAuth, setAuthToken } from "./auth";

const API = "http://localhost:5500/api/events";

function App() {
  const [user, setUser] = useState(null);
  const [events, setEvents] = useState([]);

  const fetchEvents = async () => {
    try {
      const { data } = await axios.get(API);
      setEvents(data);
    } catch (err) {
      console.log(err);
    }
  };

  useEffect(() => {
    const token = initAuth();
    if (token) setUser({}); // dummy logged-in state
    fetchEvents();
  }, []);

  const handleLogout = () => {
    setAuthToken(null);
    setUser(null);
  };

  if (!user) {
    return <AuthForm onSuccess={(usr) => setUser(usr)} />;
  }

  return (
    <Container sx={{ mt: 4 }}>
      <Button variant="outlined" onClick={handleLogout}>
        Logout
      </Button>

      <EventForm onEventAdded={fetchEvents} />

      <EventList events={events} />
    </Container>
  );
}

export default App;
